SELECT dg.gb_distributer_goods_id, dg.gb_dg_goods_name, dg.gb_dg_nx_father_img, dg.gb_dg_goods_standardname, dg.gb_dg_goods_standard_weight, dg.gb_dg_gb_supplier_id, dg.gb_dg_goods_lowest_price AS origin_lowest_price, dg.gb_dg_goods_highest_price AS origin_highest_price, ROUND(SUM(gdpg.gb_DPG_buy_subtotal), 1) AS gb_dg_selling_price, ROUND(SUM(gdpg.gb_DPG_buy_quantity), 1) AS gb_dg_self_price, CASE WHEN dg.gb_dg_goods_lowest_price IS NULL OR dg.gb_dg_goods_lowest_price = '' THEN MIN(CAST(gdpg.gb_DPG_buy_price AS DECIMAL(10,1))) ELSE CAST(dg.gb_dg_goods_lowest_price AS DECIMAL(10,1)) END AS lowest_price, CASE WHEN dg.gb_dg_goods_highest_price IS NULL OR dg.gb_dg_goods_highest_price = '' THEN MAX(CAST(gdpg.gb_DPG_buy_price AS DECIMAL(10,1))) ELSE CAST(dg.gb_dg_goods_highest_price AS DECIMAL(10,1)) END AS highest_price, ROUND(AVG(CAST(gdpg.gb_DPG_buy_price AS DECIMAL(10,1))), 1) AS average_price, COUNT(*) AS buy_count, #{date} AS date, #{startDate} AS startDate, #{stopDate} AS stopDate, #{purUserId} AS purUserId, #{supplierBuy} AS supplierBuy, #{supplierId} AS supplierId, #{typeNotEqual} AS typeNotEqual, #{batchId} AS batchId FROM gb_distributer_purchase_goods AS gdpg LEFT JOIN gb_distributer_goods AS dg ON dg.gb_distributer_goods_id = gdpg.gb_DPG_dis_goods_id LEFT JOIN gb_distributer_purchase_batch AS gdpb ON gdpb.gb_distributer_purchase_batch_id = gdpg.gb_DPG_batch_id
