SELECT g.gb_dg_goods_name, g.gb_dg_goods_standardname, g.gb_dg_nx_father_img, t.goods_id AS gb_distributer_goods_id, t.times AS gb_dg_quantity_days FROM ( SELECT gb_DPG_dis_goods_id AS goods_id, COUNT(*) AS times FROM gb_distributer_purchase_goods WHERE gb_DPG_stock_finish_date BETWEEN #{startDate} AND #{stopDate} AND gb_DPG_distributer_id = #{disId} AND gb_DPG_status > 2 AND gb_DPG_buy_subtotal > 0
AND gb_DPG_purchase_department_id = #{purDepId}
AND gb_DPG_purchase_department_id IN
#{id}
AND gb_DPG_purchase_type != #{typeNotEqual}
GROUP BY gb_DPG_dis_goods_id ) t JOIN gb_distributer_goods g ON g.gb_distributer_goods_id = t.goods_id ORDER BY t.times DESC LIMIT 10

SELECT g.gb_dg_goods_name, g.gb_dg_goods_standardname, g.gb_dg_nx_father_img, t.goods_id AS gb_distributer_goods_id, t.total_subtotal AS goodsPurTotalSubtotal FROM ( SELECT gb_DPG_dis_goods_id AS goods_id, ROUND(SUM(gb_DPG_buy_subtotal), 1) AS total_subtotal FROM gb_distributer_purchase_goods WHERE gb_DPG_stock_finish_date BETWEEN #{startDate} AND #{stopDate} AND gb_DPG_distributer_id = #{disId} AND gb_DPG_status > 2 AND gb_DPG_buy_subtotal > 0
AND gb_DPG_purchase_department_id = #{purDepId}
AND gb_DPG_purchase_department_id IN
#{id}
