         ORDER BY total_subtotal DESC
         LIMIT 10
     ) t

SELECT g.gb_dg_goods_name, g.gb_dg_goods_standardname, g.gb_dg_nx_father_img, t.goods_id AS gb_distributer_goods_id, t.max_price AS gbDgGoodsHighestPrice, t.min_price AS gbDgGoodsLowestPrice, t.price_diff AS goodsPriceDiff, t.price_fluctuation AS goodsPriceFluctuation FROM ( SELECT gb_DPG_dis_goods_id AS goods_id, MAX(CAST(TRIM(gb_DPG_buy_price) AS DECIMAL(10, 1))) AS max_price, MIN(CAST(TRIM(gb_DPG_buy_price) AS DECIMAL(10, 1))) AS min_price, ROUND((MAX(CAST(TRIM(gb_DPG_buy_price) AS DECIMAL(10, 1))) - MIN(CAST(TRIM(gb_DPG_buy_price) AS DECIMAL(10, 1)))), 1) AS price_diff, ROUND(((MAX(CAST(TRIM(gb_DPG_buy_price) AS DECIMAL(10, 1))) - MIN(CAST(TRIM(gb_DPG_buy_price) AS DECIMAL(10, 1)))) / NULLIF(MIN(CAST(TRIM(gb_DPG_buy_price) AS DECIMAL(10, 1))), 0)) * 100, 1) AS price_fluctuation FROM gb_distributer_purchase_goods WHERE gb_DPG_stock_finish_date BETWEEN #{startDate} AND #{stopDate} AND gb_DPG_distributer_id = #{disId} AND gb_DPG_buy_price IS NOT NULL AND TRIM(gb_DPG_buy_price) <> '' AND gb_DPG_status > 2
AND gb_DPG_purchase_department_id = #{purDepId}
AND gb_DPG_purchase_department_id IN
#{id}
AND gb_DPG_purchase_type != #{typeNotEqual}
GROUP BY gb_DPG_dis_goods_id HAVING MAX(CAST(TRIM(gb_DPG_buy_price) AS DECIMAL(10, 1))) > MIN(CAST(TRIM(gb_DPG_buy_price) AS DECIMAL(10, 1))) ) t JOIN gb_distributer_goods g ON g.gb_distributer_goods_id = t.goods_id ORDER BY t.price_fluctuation DESC LIMIT 10

SELECT t.dis_goods_id AS disGoodsId, t.goods_name AS goodsName, t.standard_name AS standardName, CAST(ROUND(t.current_unit_price, 2) AS CHAR) AS currentUnitPrice, CAST(ROUND(t.previous_unit_price, 2) AS CHAR) AS previousUnitPrice, CAST(ROUND( (t.current_unit_price - t.previous_unit_price) / NULLIF(t.previous_unit_price, 0) * 100, 1) AS CHAR) AS priceChangePercent, t.stock_finish_date AS stockFinishDate, t.purchase_goods_id AS currentPurchaseGoodsId, t.previous_purchase_goods_id AS previousPurchaseGoodsId FROM ( SELECT x.*, ROW_NUMBER() OVER ( PARTITION BY x.dis_goods_id ORDER BY ABS(x.current_unit_price - x.previous_unit_price) DESC, x.stock_finish_date DESC, x.purchase_goods_id DESC ) AS rn FROM ( SELECT gdpg.gb_DPG_dis_goods_id AS dis_goods_id, gdpg.gb_distributer_purchase_goods_id AS purchase_goods_id, gdpg.gb_DPG_stock_finish_date AS stock_finish_date, TRIM(IFNULL(dg.gb_dg_goods_name, '')) AS goods_name, TRIM(IFNULL(dg.gb_dg_goods_standardname, '')) AS standard_name, CAST(TRIM(gdpg.gb_DPG_buy_price) AS DECIMAL(18, 4)) AS current_unit_price, LAG(CAST(TRIM(gdpg.gb_DPG_buy_price) AS DECIMAL(18, 4))) OVER ( PARTITION BY gdpg.gb_DPG_dis_goods_id ORDER BY gdpg.gb_DPG_stock_finish_date, gdpg.gb_distributer_purchase_goods_id ) AS previous_unit_price, LAG(gdpg.gb_distributer_purchase_goods_id) OVER ( PARTITION BY gdpg.gb_DPG_dis_goods_id ORDER BY gdpg.gb_DPG_stock_finish_date, gdpg.gb_distributer_purchase_goods_id ) AS previous_purchase_goods_id FROM gb_distributer_purchase_goods AS gdpg LEFT JOIN gb_distributer_purchase_batch AS gdpb ON gdpb.gb_distributer_purchase_batch_id = gdpg.gb_DPG_batch_id LEFT JOIN gb_distributer_goods dg ON dg.gb_distributer_goods_id = gdpg.gb_DPG_dis_goods_id
AND gdpg.gb_DPG_buy_price IS NOT NULL AND TRIM(gdpg.gb_DPG_buy_price) <> ''
) x WHERE x.stock_finish_date >= #{startDate} AND x.stock_finish_date <= #{stopDate} AND x.previous_unit_price IS NOT NULL AND ABS(x.current_unit_price - x.previous_unit_price) > 0.0001 ) t WHERE t.rn = 1 ORDER BY ABS(t.current_unit_price - t.previous_unit_price) DESC LIMIT #{limit,jdbcType=INTEGER}

